SELECT b.country = 'Bangladesh', SUM(r.rating) * 1.0 / COUNT(*) FROM product_reviews r JOIN products p USING (product_id) JOIN brands b USING (brand_id) WHERE p.is_deleted = FALSE AND r.created_at >= TIMESTAMP '2026-01-01 00:00:00' AND r.created_at < TIMESTAMP '2026-03-31 00:00:00' + INTERVAL 1 DAY GROUP BY 1
